import os, pty, sys, time, select, subprocess
def run(args, keys=b'', cols=80, rows=24, wait=0.4, delay=0.05, env=None):
    pid, fd = pty.fork()
    if pid == 0:
        e = dict(os.environ)
        e['TERM'] = e.get('TERM','xterm-256color')
        if env: e.update(env)
        os.execve(args[0], args, e)
    import fcntl, termios, struct
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = b''
    def drain(t=wait):
        nonlocal out
        end = time.time()+t
        while time.time() < end:
            r,_,_ = select.select([fd],[],[],0.05)
            if r:
                try: d = os.read(fd, 65536)
                except OSError: break
                if not d: break
                out += d
                end = time.time()+t
    drain(wait)
    for k in keys:
        os.write(fd, bytes([k]))
        drain(delay)
    drain(wait)
    try: os.close(fd)
    except OSError: pass
    try: os.waitpid(pid, 0)
    except Exception: pass
    return out
if __name__ == '__main__':
    out = run(sys.argv[1:], b'')
    sys.stdout.buffer.write(out)
EOF
