{"command": "mkdir -p /tmp/h && cat > /tmp/h/vt.py <<'PYEOF'
import re
class VT:
    def __init__(self, cols=80, rows=24):
        self.cols, self.rows = cols, rows
        self.grid = [[' ']*cols for _ in range(rows)]
        self.attr = [[None]*cols for _ in range(rows)]
        self.x = self.y = 0
        self.cur = ''  # current sgr state string
    def clearline(self):
        for i in range(self.x, self.cols):
            self.grid[self.y][i] = ' '
            self.attr[self.y][i] = self.cur if False else None
    def put(self, ch):
        if self.y < self.rows and self.x < self.cols:
            self.grid[self.y][self.x] = ch
            self.attr[self.y][self.x] = self.cur
        self.x += 1
    def feed(self, data):
        i = 0
        n = len(data)
        while i < n:
            c = data[i]
            if c == '\x1b':
                m = re.match(r'\x1b\[([0-9;?]*)([A-Za-z])', data[i:])
                if m:
                    params, cmd = m.group(1), m.group(2)
                    i += m.end()
                    if cmd == 'H':
                        parts = params.split(';')
                        r = int(parts[0]) if parts[0] else 1
                        cc = int(parts[1]) if len(parts)>1 and parts[1] else 1
                        self.y = min(r-1, self.rows-1); self.x = min(cc-1, self.cols-1)
                    elif cmd == 'K':
                        self.clearline()
                    elif cmd == 'm':
                        if params == '' or params == '0':
                            self.cur = ''
                        else:
                            self.cur = params
                    elif cmd == 'J':
                        if params in ('2',''):
                            self.grid = [[' ']*self.cols for _ in range(self.rows)]
                    continue
                else:
                    i += 1
                    continue
            elif c == '\r':
                self.x = 0; i += 1; continue
            elif c == '\n':
                self.y += 1; i += 1; continue
            elif c == '\b':
                self.x = max(0,self.x-1); i += 1; continue
            elif ord(c) < 32:
                i += 1; continue
            else:
                self.put(c); i += 1
    def text(self):
        return '\n'.join(''.join(r).rstrip() for r in self.grid)
    def dump(self):
        for i,r in enumerate(self.grid):
            print('%2d|%s' % (i+1, ''.join(r).rstrip()))
PYEOF
echo done"}

