    out = run.run(['/workspace/executable',path], keys=keys, wait=0.25, delay=0.15, cols=cols)
    return out.decode('utf8','replace')
def check(name, s):
    m = re.search(r"of `(.*)`\nnote:", s, re.S)
    if m:
        snip = m.group(1); idx = re.search(r"byte index (\d+)", s).group(1)
        loc = s[s.find('panicked at'):s.find('panicked at')+50]
        print('%-30s PANIC idx=%s snip_b=%d loc=%r' % (name, idx, len(snip.encode('utf8')), loc))
    else:
        print('%-30s ok: %r' % (name, s.split('\x1b[?25l')[-1][-90:]))
# open prompt with wide chars
p = '/tmp/w3/aa.txt'
if not os.path.exists(p): open(p,'w').write('a\n')
for cols in (20, 30, 40):
    s = run2(p, cols, keys=['\x0f'] + list('\u65e5'*12))
    check('open prompt wide cols=%d'%cols, s)
# search prompt with wide chars
for cols in (20, 30, 40):
    s = run2(p, cols, keys=['\x07'] + list('\u65e5'*12))
    check('search prompt wide cols=%d'%cols, s)
EOF"}

