        cur = re.search(r'\x1b\[\?25h(\x1b\[(\d+);(\d+)H)$', seg)
        print('m=%2d bytes=%2d ok=%r cur=%s' % (m, m+3, seg[k:j][:40], cur.group(3) if cur else '?'))
EOF"}

