            if r:
                try: d = os.read(fd, 65536)
                except OSError: break
                if not d: break
                out += d
                end = time.time()+t
    drain(wait)
    chunks = [out]
    for k in keys:
        os.write(fd, k.encode('utf8','surrogateescape'))
        before = len(out)
        drain(delay)
        chunks.append(out[before:])
    try: os.close(fd)
    except OSError: pass
    code=None
