import os, pty, time, select, fcntl, termios, struct
def run_steps(args, keys, cols=80, rows=24, wait=0.18, delay=0.08, env=None, term=None, cwd=None, errfile=None):
    pid, fd = pty.fork()
    if pid == 0:
        e = dict(os.environ)
        e['TERM'] = e.get('TERM','xterm-256color')
        if term: e['TERM'] = term
        if env: e.update(env)
        if cwd is not None: os.chdir(cwd)
        if errfile is not None:
            f = os.open(errfile, os.O_WRONLY|os.O_CREAT|os.O_TRUNC, 0o644); os.dup2(f, 2)
        os.execve(args[0], args, e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = b''
    def drain(t):
        nonlocal out
        end = time.time()+t
        while time.time() < end:
            r,_,_ = select.select([fd],[],[],0.03)
            if r:
                try: d = os.read(fd, 65536)
                except OSError: break
                if not d: break
                out += d
                end = time.time()+t
    drain(wait)
    chunks = [out]
    for k in keys:
        os.write(fd, k.encode('utf8','surrogateescape'))
        before = len(out)
        drain(delay)
        chunks.append(out[before:])
    try: os.close(fd)
    except OSError: pass
    code=None
    try:
        _, st = os.waitpid(pid, 0); code = (st>>8, st&0xff)
    except Exception: pass
    err = b''
    if errfile:
        try: err = open(errfile,'rb').read()
        except Exception: pass
    return chunks, err, code
