    chunk = words[i:i+12]
    open('/tmp/hlx.jl','w').write('\n'.join(chunk)+'\n')
    chunks, err, code = step.run_steps(['/workspace/executable','/tmp/hlx.jl'], [], rows=16, cols=60, wait=0.3, delay=0.05, errfile='/tmp/e5.txt')
    s = b''.join(chunks).decode('utf8','replace')
    d = {}
    for n, segs in rows(s):
        for c,t in segs:
            if t and t != '~': d[t] = c.replace('E','').replace('m','')
    print('batch %d: %s' % (i//12, ' | '.join('%s=%s' % (w, d.get(w,'-')) for w in chunk)))
