//! Minimal terminfo database reader.
//!
//! Only the numeric capability `colors` (max_colors) is needed to decide
//! whether the terminal supports 256 colors.

pub struct Terminfo {
    pub colors: Option<i32>,
}

fn parse(data: &[u8]) -> Option<Terminfo> {
    if data.len() < 12 {
        return None;
    }
    let magic = u16::from_le_bytes([data[0], data[1]]);
    // 0x011A = legacy format, 0x021E = extended (32 bit) number format
    if magic != 0x011A && magic != 0x021E {
        return None;
    }
    let num_size: usize = if magic == 0x021E { 4 } else { 2 };
    let names_size = u16::from_le_bytes([data[2], data[3]]) as usize;
    let bools_size = u16::from_le_bytes([data[4], data[5]]) as usize;
    let nums_size = u16::from_le_bytes([data[6], data[7]]) as usize;
    let strs_size = u16::from_le_bytes([data[8], data[9]]) as usize;
    let strtab_size = u16::from_le_bytes([data[10], data[11]]) as usize;
    let mut off = 12usize;
    off += names_size;
    off += bools_size;
    if off % 2 == 1 {
        off += 1;
    }
    // numbers
    let mut colors = None;
    for i in 0..nums_size {
        if off + num_size > data.len() {
            return None;
        }
        let v = if num_size == 4 {
            i32::from_le_bytes([data[off], data[off + 1], data[off + 2], data[off + 3]])
        } else {
            let raw = u16::from_le_bytes([data[off], data[off + 1]]);
            if raw == 0xFFFF {
                -1
            } else if raw == 0xFFFE {
                -2
            } else {
                raw as i32
            }
        };
        if i == 13 {
            colors = if v < 0 { None } else { Some(v) };
        }
        off += num_size;
    }
    Some(Terminfo { colors })
}

fn try_dir(dir: &str, name: &str) -> Option<Terminfo> {
    if name.is_empty() || name.contains('/') || name.contains('\\') {
        return None;
    }
    let first = name.chars().next()?;
    let mut candidates: Vec<String> = Vec::new();
    let mut hex = String::new();
    for b in first.to_string().as_bytes() {
        hex.push_str(&format!("{:02x}", b));
    }
    candidates.push(format!("{}/{}", dir, first));
    candidates.push(format!("{}/{}", dir, hex));
    for base in candidates {
        for path in [
            format!("{}/{}", base, name),
            format!("{}.gz", format!("{}/{}", base, name)),
        ] {
            if let Ok(data) = std::fs::read(&path) {
                if let Some(info) = parse(&data) {
                    return Some(info);
                }
            }
        }
    }
    None
}

/// Look up the terminfo entry for `name` and return it.
pub fn from_name(name: &str) -> Option<Terminfo> {
    if let Ok(dir) = std::env::var("TERMINFO") {
        if let Some(info) = try_dir(&dir, name) {
            return Some(info);
        }
    }
    if let Ok(home) = std::env::var("HOME") {
        let dir = format!("{}/.terminfo", home);
        if let Some(info) = try_dir(&dir, name) {
            return Some(info);
        }
    }
    for dir in ["/etc/terminfo", "/lib/terminfo", "/usr/share/terminfo"] {
        if let Some(info) = try_dir(dir, name) {
            return Some(info);
        }
    }
    None
}

/// True when the terminal described by `$TERM` supports 256 colors.
pub fn supports_256_color() -> bool {
    match std::env::var("TERM") {
        Ok(term) => match from_name(&term) {
            Some(info) => info.colors == Some(256),
            None => false,
        },
        Err(_) => false,
    }
}
EOF
echo ok"}

