//! Text buffer with rows, syntax highlighting and undo history.

pub const TAB_WIDTH: usize = 8;

/// Display width of a character.
pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if cp < 0x20 {
        return 0;
    }
    if (0x1100..=0x115F).contains(&cp)
        || (0x2E80..=0x303E).contains(&cp)
        || (0x3041..=0x33FF).contains(&cp)
        || (0x3400..=0x4DBF).contains(&cp)
        || (0x4E00..=0x9FFF).contains(&cp)
        || (0xA000..=0xA4CF).contains(&cp)
        || (0xA960..=0xA97F).contains(&cp)
        || (0xAC00..=0xD7A3).contains(&cp)
        || (0xF300..=0xF72F).contains(&cp)
        || (0xF900..=0xFAFF).contains(&cp)
        || (0xFE30..=0xFE6F).contains(&cp)
        || (0xFF00..=0xFF60).contains(&cp)
        || (0xFFE0..=0xFFE6).contains(&cp)
    {
        return 2;
    }
    1
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

/// A single line of text.
pub struct Row {
    pub chars: Vec<char>,
    /// highlight kinds, one entry per character
    pub hl: Vec<HlKind>,
}

#[derive(Clone, Copy, PartialEq)]
pub enum HlKind {
    Normal,
    Keyword,
    Type,
    Control,
    Constant,
    Literal,
    String,
    Comment,
    Definition,
}

impl Row {
    fn new() -> Row {
        Row { chars: Vec::new(), hl: Vec::new() }
    }
    pub fn text(&self) -> String {
        self.chars.iter().collect()
    }
    pub fn is_empty(&self) -> bool {
        self.chars.is_empty()
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum Op {
    InsertChar,
    DeleteChar,
    Backspace,
    NewLine,
    DeleteWord,
    DeleteLineHead,
    DeleteLineTail,
    InsertRow,
    DeleteRow,
}

/// One atomic change, stored so it can be reverted.
#[derive(Clone)]
pub struct Change {
    pub ops: Vec<Op>,
}

pub struct TextBuffer {
    pub name: String,
    pub rows: Vec<Row>,
    pub cx: usize,
    pub cy: usize,
    /// horizontal scroll offset
    pub coloff: usize,
    /// vertical scroll offset
    pub rowoff: usize,
    pub dirty: bool,
    pub syntax: &'static crate::config::Syntax,
    /// undo history
    pub history: Vec<Change>,
    /// index into history: number of applied changes
    pub history_pos: usize,
    /// the change currently being built
    cur_ops: Vec<Op>,
    pub curser_match: Option<(usize, usize)>,
    pub search: Option<String>,
}

impl TextBuffer {
    pub fn new(name: &str, syntax: &'static crate::config::Syntax) -> TextBuffer {
        TextBuffer {
            name: name.to_string(),
            rows: Vec::new(),
            cx: 0,
            cy: 0,
            coloff: 0,
            rowoff: 0,
            dirty: false,
            syntax,
            history: Vec::new(),
            history_pos: 0,
            cur_ops: Vec::new(),
            curser_match: None,
            search: None,
        }
    }

    /// Load text. Returns Err when the text contains characters that are not
    /// allowed.
    pub fn load(&mut self, text: &str) -> Result<(), LoadError> {
        let mut rows: Vec<Row> = Vec::new();
        let mut cur = Row::new();
        for c in text.chars() {
            match c {
                '\n' => {
                    rows.push(std::mem::replace(&mut cur, Row::new()));
                }
                '\r' | '\0' => {}
                c => {
                    if (c as u32) < 0x20 {
                        return Err(LoadError::InvalidChar(c));
                    }
                    cur.chars.push(c);
                }
            }
        }
        rows.push(cur);
        // A file that ends with a newline does not create an extra empty row.
        if rows.len() > 1 && rows.last().unwrap().is_empty() && text.ends_with('\n') {
            rows.pop();
        }
        self.rows = rows;
        self.highlight_all();
        Ok(())
    }

    pub fn text(&self) -> String {
        let mut s = String::new();
        for (i, row) in self.rows.iter().enumerate() {
            if i > 0 {
                s.push('\n');
            }
            s.push_str(&row.text());
        }
        if !self.rows.is_empty() {
            s.push('\n');
        }
        s
    }

    pub fn row(&self, i: usize) -> Option<&Row> {
        self.rows.get(i)
    }

    pub fn highlight_all(&mut self) {
        let mut state = HlState::default();
        for i in 0..self.rows.len() {
            self.highlight_row(i, &mut state);
        }
    }

    /// Recompute highlighting of rows starting at `start`.
    pub fn highlight_from(&mut self, start: usize) {
        let mut state = if start == 0 {
            HlState::default()
        } else {
            state_after(self, start)
        };
        for i in start..self.rows.len() {
            self.highlight_row(i, &mut state);
        }
    }

    fn highlight_row(&mut self, i: usize, state: &mut HlState) {
        let syntax = self.syntax;
        let chars = self.rows[i].chars.clone();
        let hl = crate::config::highlight_row(syntax, &chars, state);
        self.rows[i].hl = hl;
    }

    // ---- editing ----

    fn record(&mut self, op: Op) {
        self.cur_ops.push(op);
    }

    pub fn begin_change(&mut self, op: Op) {
        // A change is broken when the operation kind differs from the one
        // currently being accumulated.
        let same_kind = match (self.cur_ops.last(), &op) {
            (Some(a), b) => op_kind(a) == op_kind(b),
            (None, _) => false,
        };
        if !same_kind {
            self.flush_change();
            self.cur_ops = Vec::new();
        }
        self.cur_ops.push(op);
    }

    pub fn flush_change(&mut self) {
        if !self.cur_ops.is_empty() {
            let ops = std::mem::take(&mut self.cur_ops);
            self.history.truncate(self.history_pos);
            self.history.push(Change { ops });
            self.history_pos = self.history.len();
        }
    }

    pub fn is_modified(&self) -> bool {
        self.dirty
    }

    pub fn insert_char(&mut self, c: char) {
        self.ensure_row();
        let cy = self.cy.min(self.rows.len() - 1);
        let cx = self.cx.min(self.rows[cy].chars.len());
        self.rows[cy].chars.insert(cx, c);
        self.cx = cx + 1;
        self.dirty = true;
        self.record(Op::InsertChar);
        self.highlight_from(cy);
    }

    fn ensure_row(&mut self) {
        while self.rows.len() <= self.cy {
            self.rows.push(Row::new());
            let hl = vec![HlKind::Normal];
            self.rows.last_mut().unwrap().hl = hl;
        }
    }

    pub fn delete_backward(&mut self) {
        if self.cy < self.rows.len() && self.cx > 0 {
            let cy = self.cy;
            self.cx -= 1;
            let cx = self.cx;
            if cx < self.rows[cy].chars.len() {
                self.rows[cy].chars.remove(cx);
            }
            self.dirty = true;
            self.record(Op::Backspace);
            self.highlight_from(cy);
        } else if self.cy > 0 && !self.rows.is_empty() {
            // join with the previous line
            let cy = self.cy;
            let prev_len = self.rows[cy - 1].chars.len();
            let cur: Vec<char> = self.rows.remove(cy).chars;
            self.rows[cy - 1].chars.extend(cur);
            self.cy = cy - 1;
            self.cx = prev_len;
            self.dirty = true;
            self.record(Op::Backspace);
            self.highlight_from(cy - 1);
        }
    }

    pub fn delete_forward(&mut self) {
        if self.cy < self.rows.len() {
            if self.cx < self.rows[self.cy].chars.len() {
                let cy = self.cy;
                let cx = self.cx;
                self.rows[cy].chars.remove(cx);
                self.dirty = true;
                self.record(Op::DeleteChar);
                self.highlight_from(cy);
            } else if self.cy + 1 < self.rows.len() {
                let cy = self.cy;
                let cur: Vec<char> = self.rows.remove(cy + 1).chars;
                self.rows[cy].chars.extend(cur);
                self.dirty = true;
                self.record(Op::DeleteChar);
                self.highlight_from(cy);
            }
        }
    }

    pub fn insert_newline(&mut self) {
        self.ensure_row();
        let cy = self.cy.min(self.rows.len() - 1);
        let cx = self.cx.min(self.rows[cy].chars.len());
        let tail: Vec<char> = self.rows[cy].chars.split_off(cx);
        let mut tail_hl = self.rows[cy].hl.split_off(cx);
        let mut newrow = Row::new();
        newrow.chars = tail;
        newrow.hl = tail_hl;
        self.rows.insert(cy + 1, newrow);
        self.cy = cy + 1;
        self.cx = 0;
        self.dirty = true;
        self.record(Op::NewLine);
        self.highlight_from(cy);
    }

    pub fn delete_word(&mut self) {
        let cy = self.cy;
        if cy >= self.rows.len() {
            return;
        }
        let mut cx = self.cx;
        let chars = &self.rows[cy].chars;
        let is_space = |c: char| c == ' ' || c == '\t';
        let is_word = |c: char| c.is_alphanumeric() || c == '_';
        if cx > 0 {
            let cls = if is_space(chars[cx - 1]) {
                1
            } else if is_word(chars[cx - 1]) {
                2
            } else {
                3
            };
            if cls == 1 {
                while cx > 0 && is_space(chars[cx - 1]) {
                    cx -= 1;
                }
            }
            if cx > 0 {
                let cls2 = if is_word(chars[cx - 1]) {
                    2
                } else {
                    3
                };
                while cx > 0 && (is_word(chars[cx - 1]) == (cls2 == 2) || is_space(chars[cx - 1]) && cls == 1) {
                    if is_word(chars[cx - 1]) != (cls2 == 2) {
                        break;
                    }
                    cx -= 1;
                }
            }
        }
        let removed = self.cx - cx;
        if removed > 0 {
            let _ = self.cx;
            self.rows[cy].chars.drain(cx..cx + removed);
            self.cx = cx;
            self.dirty = true;
            self.record(Op::DeleteWord);
            self.highlight_from(cy);
        }
    }

    pub fn delete_line_head(&mut self) {
        let cy = self.cy;
        if cy >= self.rows.len() || self.cx == 0 {
            return;
        }
        self.rows[cy].chars.drain(0..self.cx);
        self.cx = 0;
        self.dirty = true;
        self.record(Op::DeleteLineHead);
        self.highlight_from(cy);
    }

    pub fn delete_line_tail(&mut self) {
        let cy = self.cy;
        if cy >= self.rows.len() {
            return;
        }
        let len = self.rows[cy].chars.len();
        if self.cx < len {
            self.rows[cy].chars.drain(self.cx..);
            self.dirty = true;
            self.record(Op::DeleteLineTail);
            self.highlight_from(cy);
        }
    }

    // ---- undo / redo ----

    pub fn undo(&mut self) -> bool {
        if self.history_pos == 0 {
            return false;
        }
        self.history_pos -= 1;
        // restore the buffer content by replaying: easiest is to keep snapshots
        if let Some(snapshot) = self.snapshots.get(self.history_pos) {
            self.rows = snapshot.rows.clone();
            self.cy = snapshot.cy;
            self.cx = snapshot.cx;
            self.dirty = true;
            self.highlight_all();
        }
        true
    }

    pub fn redo(&mut self) -> bool {
        if self.history_pos >= self.snapshots.len() {
            return false;
        }
        let snapshot = self.snapshots[self.history_pos].clone();
        self.history_pos += 1;
        self.rows = snapshot.rows.clone();
        self.cy = snapshot.cy;
        self.cx = snapshot.cx;
        self.dirty = true;
        self.highlight_all();
        true
    }

    // ---- cursor movement ----

    pub fn move_left(&mut self) {
        if self.cx > 0 {
            self.cx -= 1;
        } else if self.cy > 0 {
            self.cy -= 1;
            self.cx = self.rows.get(self.cy).map(|r| r.chars.len()).unwrap_or(0);
        }
    }

    pub fn move_right(&mut self) {
        let len = self.rows.get(self.cy).map(|r| r.chars.len()).unwrap_or(0);
        if self.cx < len {
            self.cx += 1;
        } else if self.cy < self.rows.len() {
            self.cy += 1;
            self.cx = 0;
        }
    }

    pub fn move_up(&mut self) {
        if self.cy > 0 {
            self.cy -= 1;
            let len = self.rows.get(self.cy).map(|r| r.chars.len()).unwrap_or(0);
            if self.cx > len {
                self.cx = len;
            }
        }
    }

    pub fn move_down(&mut self) {
        if self.cy < self.rows.len() {
            self.cy += 1;
            let len = self.rows.get(self.cy).map(|r| r.chars.len()).unwrap_or(0);
            if self.cx > len {
                self.cx = len;
            }
        }
    }

    pub fn move_head(&mut self) {
        self.cx = 0;
    }

    pub fn move_tail(&mut self) {
        self.cx = self.rows.get(self.cy).map(|r| r.chars.len()).unwrap_or(0);
    }

    pub fn move_top(&mut self) {
        self.cy = 0;
        self.cx = 0;
    }

    pub fn move_bottom(&mut self) {
        self.cy = self.rows.len();
        self.cx = 0;
    }

    pub fn next_word(&mut self) {
        let mut cy = self.cy;
        let mut cx = self.cx;
        let cls = |c: char| -> u8 {
            if c == ' ' || c == '\t' {
                0
            } else if c.is_alphanumeric() || c == '_' {
                1
            } else {
                2
            }
        };
        loop {
            let row = match self.rows.get(cy) {
                Some(r) => r,
                None => break,
            };
            let mut moved = false;
            if cx < row.chars.len() {
                cx += 1;
                moved = true;
            }
            if moved && cx < row.chars.len() {
                let cl = cls(row.chars[cx]);
                while cx < row.chars.len() && cls(row.chars[cx]) == cl {
                    cx += 1;
                }
                while cx < row.chars.len() && cls(row.chars[cx]) == 0 {
                    cx += 1;
                }
            }
            if cx >= row.chars.len() {
                if cy + 1 < self.rows.len() {
                    cy += 1;
                    cx = 0;
                    continue;
                } else {
                    cy += 1;
                    cx = 0;
                    break;
                }
            }
            break;
        }
        self.cy = cy;
        self.cx = cx;
    }

    pub fn prev_word(&mut self) {
        let mut cy = self.cy;
        let mut cx = self.cx;
        let cls = |c: char| -> u8 {
            if c == ' ' || c == '\t' {
                0
            } else if c.is_alphanumeric() || c == '_' {
                1
            } else {
                2
            }
        };
        loop {
            if cx == 0 {
                if cy == 0 {
                    break;
                }
                cy -= 1;
                cx = self.rows[cy].chars.len();
                continue;
            }
            cx -= 1;
            while cx > 0 && cls(self.rows[cy].chars[cx]) == 0 {
                cx -= 1;
            }
            let cl = cls(self.rows[cy].chars[cx]);
            while cx > 0 && cls(self.rows[cy].chars[cx - 1]) == cl {
                cx -= 1;
            }
            break;
        }
        self.cy = cy;
        self.cx = cx;
    }

    pub fn next_paragraph(&mut self) {
        let mut j = self.cy + 1;
        while j < self.rows.len() {
            if !self.rows[j].is_empty() && (j == 0 || self.rows[j - 1].is_empty()) {
                break;
            }
            j += 1;
        }
        self.cy = j.min(self.rows.len());
        self.cx = 0;
    }

    pub fn prev_paragraph(&mut self) {
        let mut j = self.cy;
        while j > 0 {
            j -= 1;
            if !self.rows[j].is_empty() && (j == 0 || self.rows[j - 1].is_empty()) {
                break;
            }
        }
        self.cy = j;
        self.cx = 0;
    }
}

#[derive(Default, Clone, Copy)]
pub struct HlState {
    pub in_string: Option<char>,
    pub in_block_comment: bool,
    pub pending_def: bool,
}

pub fn state_after(buf: &TextBuffer, row: usize) -> HlState {
    let syntax = buf.syntax;
