fn ctrl_name(c: char) -> String {
    match c {
        ' ' => "SPACE".to_string(),
        _ => c.to_string(),
    }
}

fn alt_name(c: char) -> String {
    match c {
        ' ' => "SPACE".to_string(),
        _ => c.to_string(),
    }
}

/// Map a control byte to its key character, following the usual conventions.
fn ctrl_char(b: u8) -> Option<char> {
    Some(match b {
        0x00 => ' ',
        0x1c => '\\',
        0x1d => ']',
        0x1e => '~',
        0x1f => '?',
        _ => {
            if (0x01..=0x1a).contains(&b) {
                (b + 0x60) as char
            } else {
                return None;
            }
        }
    })
}

pub struct Input<R: std::io::Read> {
    reader: R,
    buf: Vec<u8>,
}

impl<R: std::io::Read> Input<R> {
    pub fn new(reader: R) -> Input<R> {
        Input { reader, buf: Vec::new() }
    }

    fn fill(&mut self) -> std::io::Result<usize> {
        let mut tmp = [0u8; 1024];
        match self.reader.read(&mut tmp) {
            Ok(n) => {
                self.buf.extend_from_slice(&tmp[..n]);
                Ok(n)
            }
            Err(e) => Err(e),
        }
    }

    fn read_byte(&mut self) -> std::io::Result<u8> {
        while self.buf.is_empty() {
            self.fill()?;
        }
        Ok(self.buf.remove(0))
    }

    /// Read one input sequence.
    pub fn next_key(&mut self) -> std::io::Result<Key> {
        let b = self.read_byte()?;
        match b {
            0x1b => self.read_escape(),
            0x09 => Ok(Key::Char('\t')),
            0x7f => Ok(Key::Backspace),
            0x00..=0x1f => match ctrl_char(b) {
                Some(c) => Ok(Key::Ctrl(c)),
                None => Ok(Key::None_),
            },
            b if b < 0x80 => Ok(Key::Char(b as char)),
            b => {
                // UTF-8 continuation
                let extra = if b >= 0xf0 {
                    3
                } else if b >= 0xe0 {
                    2
                } else {
                    1
                };
                let mut bytes = vec![b];
                for _ in 0..extra {
                    bytes.push(self.read_byte()?);
                }
                match std::str::from_utf8(&bytes) {
                    Ok(s) => match s.chars().next() {
                        Some(c) => Ok(Key::Char(c)),
                        None => Ok(Key::None_),
                    },
                    Err(_) => Ok(Key::None_),
                }
            }
        }
    }

    fn read_escape(&mut self) -> std::io::Result<Key> {
        let b = self.read_byte()?;
        match b {
            b'[' => self.read_csi(),
            c => Ok(Key::Alt(c as char)),
        }
    }

    fn read_csi(&mut self) -> std::io::Result<Key> {
        let mut params: Vec<u8> = Vec::new();
        loop {
            let b = self.read_byte()?;
            if (0x30..=0x3f).contains(&b) {
                params.push(b);
            } else {
                let modifier = parse_modifier(&params);
                return Ok(match b {
                    b'A' => arrow(Key::Up, modifier),
                    b'B' => arrow(Key::Down, modifier),
                    b'C' => arrow(Key::Right, modifier),
                    b'D' => arrow(Key::Left, modifier),
                    b'H' => Key::Home,
                    b'F' => Key::End,
                    b'~' => {
                        let first = params
                            .split(|c| *c == b';')
                            .next()
                            .unwrap_or(&[])
                            .iter()
                            .map(|c| c - b'0')
                            .fold(0usize, |acc, d| acc * 10 + d as usize);
                        match first {
                            1 => Key::Home,
                            3 => Key::Delete,
                            4 => Key::End,
                            5 => Key::PageUp,
                            6 => Key::PageDown,
                            7 => Key::Home,
                            8 => Key::End,
                            _ => Key::None_,
                        }
                    }
                    b'Z' => Key::None_,
                    b'M' => Key::None_,
                    _ => Key::None_,
                });
            }
        }
    }
}

fn parse_modifier(params: &[u8]) -> bool {
    params.contains(&b'5') || params.contains(&b'3')
}

fn arrow(base: Key, _modifier: bool) -> Key {
    base
}
